mapper.select:
SELECT bill.bill_id AS billingId, COD01.item1 AS paymentMethod, convert_from(decrypt(bill.billing_name, #{cryptKey}::bytea, 'aes'), 'UTF8') AS billingName, coalesce(convert_from(decrypt(bill.billing_address1, #{cryptKey}::bytea, 'aes'), 'UTF8'), '') || coalesce(convert_from(decrypt(bill.billing_address2, #{cryptKey}::bytea, 'aes'), 'UTF8'), '') AS billingAddress, COD02.item1 AS customerType, JGS.business_id AS RateOutbreakIdSearch, JGS.business_name AS RateOutbreak, JGS.bill_business_id AS RequestCompanyId, '' AS RateOutbreakIdDisplay, bill.cooperation_bill_id AS BillingDestinationIdDisplay FROM t_billing bill INNER JOIN m_business AS JGS ON bill.charge_occur_business_id = JGS.business_id LEFT OUTER JOIN (SELECT code, item1 FROM m_code WHERE class = '01' and "group" = '6') COD01 ON bill.payment_method = COD01.code LEFT OUTER JOIN (SELECT code, item1 FROM m_code WHERE class = '01' and "group" = '21') COD02 ON bill.individual_corporation_classification = COD02.code
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_gas_bill_info AS gbi ON gbi.contract_id = sct.contract_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND gbi.feed_point_number LIKE #{GBI_FEED_POINT_NUMBER} )
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_gas_need_contract AS gnc ON gnc.contract_id = sct.contract_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND gnc.old_number LIKE #{GND_OLD_NUMBER} AND gnc.deleted_flg = '0' )
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_gas_bill_info AS gbi ON gbi.contract_id = sct.contract_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND gbi.billing_year_month = #{GBI_BILLING_YEAR_MONTH} )
AND bill.bill_id LIKE #{BILLINGDESTINATION_ID}
AND convert_from(decrypt(bill.bill_phone_number1, #{cryptKey}::bytea, 'aes'), 'UTF8') LIKE #{BILLINGPHONE_NUMBER}
AND convert_from(decrypt(bill.billing_name, #{cryptKey}::bytea, 'aes'), 'UTF8') LIKE #{BILLING_NAME}
AND convert_from(decrypt(bill.billing_name_cana, #{cryptKey}::bytea, 'aes'), 'UTF8') LIKE #{BILLING_NAME_KANA}
AND (coalesce(convert_from(decrypt(bill.billing_address1, #{cryptKey}::bytea, 'aes'), 'UTF8'), '') || coalesce(convert_from(decrypt(bill.billing_address2, #{cryptKey}::bytea, 'aes'), 'UTF8'), '')) LIKE #{BILLING_ADDRESS}
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_business_customer_contractor AS bcc ON bcc.charges_occur_business_id = sct.charges_occur_business_id AND bcc.customer_id = sct.customer_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND sct.contract_id LIKE #{SCT_CONTRACT_ID} )
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_business_customer_contractor AS bcc ON bcc.charges_occur_business_id = sct.charges_occur_business_id AND bcc.customer_id = sct.customer_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND convert_from(decrypt(bcc.contractor_phone_number1, #{cryptKey}::bytea, 'aes'), 'UTF8') LIKE #{BCC_CONTRACT_PHONE_NUMBER} )
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_business_customer_contractor AS bcc ON bcc.charges_occur_business_id = sct.charges_occur_business_id AND bcc.customer_id = sct.customer_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND convert_from(decrypt(bcc.consumer_name, #{cryptKey}::bytea, 'aes'), 'UTF8') LIKE #{BCC_CONSUMER_NAME} )
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_business_customer_contractor AS bcc ON bcc.charges_occur_business_id = sct.charges_occur_business_id AND bcc.customer_id = sct.customer_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND convert_from(decrypt(bcc.consumer_name_kana, #{cryptKey}::bytea, 'aes'), 'UTF8') LIKE #{BCC_CONSUMER_NAME_KANA} )
AND EXISTS ( SELECT 1 FROM t_service_contract sct INNER JOIN t_business_customer_contractor AS bcc ON bcc.charges_occur_business_id = sct.charges_occur_business_id AND bcc.customer_id = sct.customer_id WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND (coalesce(convert_from(decrypt(bcc.contractor_address1, #{cryptKey}::bytea, 'aes'), 'UTF8'), '') || coalesce(convert_from(decrypt(bcc.contractor_address2, #{cryptKey}::bytea, 'aes'), 'UTF8'), '')) LIKE #{BCC_CONTRACTOR_ADDRESS} )
AND EXISTS ( SELECT 1 FROM t_service_contract sct WHERE bill.bill_business_operator_id = sct.bill_business_operator_id AND bill.bill_id = sct.bill_id AND sct.service_type = '20' AND sct.deleted_flg = '0' )
ORDER BY billingId LIMIT #{size} OFFSET #{offset}
